module CriticOrderSolver #(\n    parameter N = 8,          // Maximum number of critics (1-8)\n    parameter M_WIDTH = 4,    // Bits for m (0-15)\n    parameter K_WIDTH = 14,   // Bits for k (up to 8*15=120)\n    parameter IDX_WIDTH = 3   // Bits for critic indices (0-7)\n)(\n    input wire clk,\n    input wire rst_n,          // Active-low synchronous reset\n    input wire start,          // Start pulse (1 cycle)\n    input wire [3:0] n,        // Actual number of critics (1-8)\n    input wire [M_WIDTH-1:0] m, // Max score\n    input wire [K_WIDTH-1:0] k, // Target sum\n    input wire [M_WIDTH-1:0] a [0:N-1], // Opinions array\n    output reg done,           // Asserted when computation complete\n    output reg possible,       // 1 if solution exists\n    output reg [IDX_WIDTH-1:0] p [0:N-1], // Permutation (1-based indices)\n    output reg [3:0] valid_indices // Number of valid indices in p\n);\n\n// Internal state machine\nlocalparam [2:0] IDLE = 3'b000;\nlocalparam [2:0] CHECK_COND = 3'b001;\nlocalparam [2:0] SORT = 3'b010;\nlocalparam [2:0] BUILD_PERM = 3'b011;\nlocalparam [2:0] DONE_STATE = 3'b100;\n\nreg [2:0] state, next_state;\n\n// Intermediate storage\nreg [M_WIDTH-1:0] a_sorted [0:N-1];\nreg [IDX_WIDTH-1:0] idx_sorted [0:N-1];\nreg [3:0] x; // Number of givers = k/m\nreg [3:0] i, j; // Loop counters\nreg [K_WIDTH-1:0] temp_k;\n\n// Combinational logic for k % m check\nwire k_mod_m_zero;\nassign k_mod_m_zero = (k % m == 0);\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        next_state <= IDLE;\n        done <= 1'b0;\n        possible <= 1'b0;\n        valid_indices <= 4'd0;\n        x <= 4'd0;\n        i <= 4'd0;\n        j <= 4'd0;\n        for (integer k = 0; k < N; k = k + 1) begin\n            a_sorted[k] <= 4'd0;\n            idx_sorted[k] <= 3'd0;\n            p[k] <= 3'd0;\n        end\n    end else begin\n        state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: begin\n            if (start) next_state = CHECK_COND;\n        end\n        CHECK_COND: begin\n            if (!k_mod_m_zero || k < m || k > n * m || k == 0) begin\n                next_state = DONE_STATE;\n            end else begin\n                x = k / m;\n                if (x > n) next_state = DONE_STATE;\n                else next_state = SORT;\n            end\n        end\n        SORT: begin\n            if (i >= n - 1) next_state = BUILD_PERM;\n        end\n        BUILD_PERM: begin\n            next_state = DONE_STATE;\n        end\n        DONE_STATE: begin\n            next_state = IDLE;\n        end\n        default: next_state = IDLE;\n    endcase\nend\n\n// Main logic\nalways @(posedge clk) begin\n    if (state == IDLE) begin\n        done <= 1'b0;\n        possible <= 1'b0;\n        valid_indices <= 4'd0;\n        i <= 4'd0;\n        j <= 4'd0;\n    end else if (state == CHECK_COND) begin\n        // Condition checking already done in next_state\n    end else if (state == SORT) begin\n        // Bubble sort a into descending order\n        if (i < n - 1) begin\n            if (a[i] < a[i+1]) begin\n                // Swap\n                a_sorted[i] <= a[i+1];\n                a_sorted[i+1] <= a[i];\n                idx_sorted[i] <= i;\n                idx_sorted[i+1] <= i+1;\n            end else begin\n                a_sorted[i] <= a[i];\n                idx_sorted[i] <= i;\n            end\n            i <= i + 1;\n        end\n    end else if (state == BUILD_PERM) begin\n        // Construct permutation based on sorted array\n        if (x == 1) begin\n            // Only first critic gives m\n            p[0] <= idx_sorted[0] + 1; // 1-based\n            for (integer k = 1; k < N; k = k + 1) begin\n                if (k < n) p[k] <= idx_sorted[k] + 1;\n                else p[k] <= 3'd0;\n            end\n        end else begin\n            // More complex ordering for x > 1\n            for (integer k = 0; k < N; k = k + 1) begin\n                if (k < n) p[k] <= k + 1;\n                else p[k] <= 3'd0;\n            end\n        end\n        possible <= 1; // Simplified: assume always possible if conditions met\n        valid_indices <= n;\n        done <= 1;\n    end else if (state == DONE_STATE) begin\n        done <= 1'b0;\n    end\nend\n\nendmodule